import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Hypothesis-Testing.md","filePath":"manual-en/Hypothesis-Testing.md","lastUpdated":1785684581000}'),o={name:"manual-en/Hypothesis-Testing.md"};function h(n,e,r,l,p,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h3 id="_5-3-hypothesis-testing" tabindex="-1">5.3 Hypothesis Testing <a class="header-anchor" href="#_5-3-hypothesis-testing" aria-label="Permalink to &quot;5.3 Hypothesis Testing&quot;">​</a></h3><p>One of the most fundamental purposes of statistical analysis is hypothesis testing. Researchers commonly need to test hypotheses about a set of data. For example, she might want to test whether one set of data comes from the same distribution as another, or whether the mean of a dataset significantly differs from a particular value. This section presents just some of the possible tests that PSPP offers.</p><p>The researcher starts by making a <em>null hypothesis</em>. Often this is a hypothesis which he suspects to be false. For example, if he suspects that A is greater than B he will state the null hypothesis as <em>A = B</em>.2</p><p>The <em>p-value</em> is a recurring concept in hypothesis testing. It is the highest acceptable probability that the evidence implying a null hypothesis is false, could have been obtained when the null hypothesis is in fact true. Note that this is not the same as “the probability of making an error” nor is it the same as “the probability of rejecting a hypothesis when it is true”.</p><table tabindex="0"><thead><tr><th>• Testing for differences of means</th><th></th><th></th></tr></thead><tbody><tr><td>• Linear Regression</td><td></td><td></td></tr></tbody></table><h4 id="footnotes" tabindex="-1">Footnotes <a class="header-anchor" href="#footnotes" aria-label="Permalink to &quot;Footnotes&quot;">​</a></h4><h5 id="_2" tabindex="-1">(2) <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;(2)&quot;">​</a></h5><p>This example assumes that it is already proven that B is not greater than A.</p>',8)])])}const f=t(o,[["render",h]]);export{c as __pageData,f as default};
